import sys

def count_distinct(cc, l, r):
    used = [False] * 24
    count = 0
    for i in range(l, r + 1):
        c = cc[i]
        if not used[c]:
            used[c] = True
            count += 1
    return count

def main():
    input_line = sys.stdin.readline().strip()
    a, b, l, r = map(int, input_line.split())
    l -= 1
    r -= 1
    totalAB = a + b
    repetitions = 4
    pattern = [0] * (totalAB * repetitions)
    offsetH = l // totalAB
    l -= offsetH * totalAB
    r -= offsetH * totalAB
    segmentCount = (r - l + 1) // totalAB
    if segmentCount > 2:
        r -= (segmentCount - 2) * totalAB
    diff = max(a - b, 1)
    for rep in range(repetitions):
        for k in range(a - diff):
            pattern[totalAB * rep + k] = k
        for k in range(diff):
            pattern[totalAB * rep + a - diff + k] = (a - diff + k) if rep % 2 == 0 else a + k
    minCount = a + a
    for shiftA in range(1, diff + 1):
        for k in range(b):
            pattern[totalAB * 0 + a + k] = pattern[totalAB * 0 + a - shiftA]
        for shiftB1 in range(1, diff + 1):
            for k in range(b):
                pattern[totalAB * 1 + a + k] = pattern[totalAB * 1 + a - shiftB1]
            for shiftB2 in range(1, diff + 1):
                for k in range(b):
                    pattern[totalAB * 2 + a + k] = pattern[totalAB * 2 + a - shiftB2]
                for shiftB3 in range(1, diff + 1):
                    for k in range(b):
                        pattern[totalAB * 3 + a + k] = pattern[totalAB * 3 + a - shiftB3]
                    minCount = min(minCount, count_distinct(pattern, l, r))
    print(minCount)

if __name__ == "__main__":
    main()

